        to_account = request.values.get('to')
        amount = request.values.get('amount')

        # --------------------------------------------
        conn = sqlite3.connect('vulnerable_app.db')
        cursor = conn.cursor()
        cursor.execute(f"UPDATE accounts SET balance = balance - {amount} WHERE username = '{from_account}'")
